package com.pocketstudio.model.tuto

/**
 * Tour 7, P7 (docs/audits/ultra/tour-7-plan-p6-p7.md § 2): one moment per consigne. A step's moments are each
 * preparation button the engine asks for (a [TutoNeed]: its label is generated by the panel) and then each series of
 * gestures its text asks for. In Facile one moment is on screen: the first unmet need's button, else the text; so a
 * Facile text never names an engine button and asks for one series of gestures at most.
 *
 * The counter is the one of the tour 6 and 7 content tests (an imperative verb at the start of a clause, a « Copier » or
 * « Passer à » pressed on its own, a verbless gesture chained by « puis »), minus the reading verbs (what is heard or
 * looked at is no gesture) and minus the gestures on an engine button (they are the need's moment).
 */
object TutoMoments {
    /** The imperative verbs of a gesture (« touche », « monte »…): a whitelist, the 2nd person singular. */
    val VERBS = (
        "touche appuie allume éteins écris fais crée mets règle monte baisse nomme ajoute efface choisis copie donne glisse " +
            "écoute regarde passe ouvre tourne pose exporte partage automatise envoie coupe garde change décale dessine enlève retire " +
            "tape joue enregistre remplis active vide prends recopie laisse place tire descends reviens essaie compare sélectionne " +
            "duplique renomme maintiens utilise transpose déplace refais remets termine finis vérifie trace supprime colle lance " +
            "arrête ralentis accélère accorde"
        ).split(' ')

    /** What is heard, looked at or checked: no gesture. */
    val READING = setOf("écoute", "regarde", "vérifie", "compare")

    /**
     * The start of the engine's preparation buttons, as `needLabel` (app) writes them in French: a Facile text never
     * names them, the panel shows them as the step's first moment.
     */
    val ENGINE_BUTTONS = listOf(
        "Créer la piste", "Passer à", "Copier sur", "Copier la basse une octave", "Créer la partie", "Nommer la partie",
        "Donner les durées conseillées", "Aller dans la partie", "Poser ce qui manque",
    )

    /** Where a gesture starts: the text's start, after « : », « . », « , »… or « puis », « et », « ensuite ». */
    private const val START = """(?:^|[:.;,(!?]|\bpuis|\bet|\bensuite|\benfin|\babord|\balors|\bou)"""
    private val ACT = Regex(START + """\s*(""" + VERBS.joinToString("|") + """|appui long)(?=[\s\-,:.]|$)""", RegexOption.IGNORE_CASE)
    private val VERB = Regex("""(?:^|[\s,])(?:""" + VERBS.joinToString("|") + """|appui long)(?=[\s\-,:.]|$)""", RegexOption.IGNORE_CASE)
    /** « puis » followed by what to write, with no verb of its own (« puis les accents », « puis sur le pad »). */
    private val CHAINED = Regex("""\bpuis\s+(?:les|la|le|l'|ceux|celles|celle|celui|un|une|des|sur|à|au|\d)""", RegexOption.IGNORE_CASE)
    private val LISTENED = Regex("""^\s*(?:écoute|regarde)\b""", RegexOption.IGNORE_CASE)
    private val QUOTED = Regex("""«\s*([^»]*?)\s*»""")
    /** A gesture whose object is an engine button (« touche « Créer la piste Basse » », « puis « Copier… » »). */
    private val ON_BUTTON = Regex("""^\s*(?:sur\s+|encore\s+)?«B»""")

    /** The engine buttons [text] names, in order (each quoted label that starts like one of [ENGINE_BUTTONS]). */
    fun engineButtons(text: String): List<String> =
        QUOTED.findAll(text).map { it.groupValues[1] }.filter(::isEngineButton).toList()

    private fun isEngineButton(label: String) = ENGINE_BUTTONS.any { label.startsWith(it) }

    /** [text] with each engine button quoted as «B» and every other quote emptied («»): the counter reads no label. */
    private fun plain(text: String) = QUOTED.replace(text) { if (isEngineButton(it.groupValues[1])) "«B»" else "«»" }

    /** The series of gestures [text] asks for, in order: no reading verb, no gesture on an engine button. */
    fun series(text: String): List<String> {
        val plain = plain(text)
        val acts = ACT.findAll(plain).filter { m ->
            val verb = m.groupValues[1].lowercase()
            verb !in READING && !ON_BUTTON.containsMatchIn(plain.substring(m.range.last + 1))
        }.map { it.value.trim() }
        val chained = CHAINED.findAll(plain).filter { m ->
            val clause = plain.substring(m.range.last + 1).split(Regex("[.;:]"), 2).first()
            val sentence = plain.substring(0, m.range.first).split(Regex("[.;:!?]")).last()
            // In a sentence that listens (« Écoute la Montée : …, puis la tension »), a « puis » orders what is heard.
            !VERB.containsMatchIn(clause) && !LISTENED.containsMatchIn(sentence) && !listens(plain, m.range.first)
        }.map { it.value }
        return (acts + chained).toList()
    }

    /** A consigne that starts with « Écoute » or « Regarde » and has no « À toi » before [at]: what follows is heard. */
    private fun listens(plain: String, at: Int): Boolean = LISTENED.containsMatchIn(plain) && "À toi" !in plain.substring(0, at)

    /** The known Facile steps still breaking the rule, « style/id kind » (kind: engine or series); blocs 1 to 4 empty it. */
    val EXCEPTIONS: Set<String> by lazy {
        TutoMoments::class.java.classLoader?.getResourceAsStream(EXCEPTIONS_FILE)?.bufferedReader()?.useLines { lines ->
            lines.map { it.trim() }.filter { it.isNotEmpty() && !it.startsWith("#") }.toSet()
        } ?: emptySet()
    }

    const val EXCEPTIONS_FILE = "tuto-moment-exceptions.txt"

    /** The moment problems of a Facile step's text, as « engine » / « series » with what was found. */
    fun problems(text: String): List<Pair<String, String>> {
        val out = ArrayList<Pair<String, String>>()
        engineButtons(text).takeIf { it.isNotEmpty() }?.let { out += "engine" to it.joinToString { b -> "« $b »" } }
        series(text).takeIf { it.size > 1 }?.let { out += "series" to "${it.size} series $it" }
        return out
    }
}
